property.value:
let $repeats := ('ForeachStatement', 'ForStatement', 'WhileStatement', 'DoStatement'),
    $iterating := ('forEach', 'forEachOrdered', 'map', 'flatMap', 'filter', 'anyMatch', 'allMatch', 'noneMatch',
                   'peek', 'removeIf', 'mapToObj', 'mapToInt', 'mapToLong', 'mapToDouble', 'takeWhile', 'dropWhile'),
    $mutators := ('add', 'addAll', 'remove', 'removeAll', 'removeIf', 'retainAll', 'clear', 'set', 'sort',
                  'replaceAll', 'addFirst', 'addLast', 'removeFirst', 'removeLast'),
    $body := function($lambda) {
      if ($lambda/*[2][self::Block]) then $lambda/*[2][count(*) = 1]/ReturnStatement/*[1] else $lambda/*[2]
    },
    $sides := function($e) {
      if ($e/self::MethodCall[@MethodName = 'equals'][ArgumentList/@Size = 1][not(*[1][self::TypeExpression])])
      then ($e/*[1], $e/ArgumentList/*[1])
      else if ($e/self::MethodCall[@MethodName = 'equals'][ArgumentList/@Size = 2]
                 [*[1][self::TypeExpression][pmd-java:typeIs('java.util.Objects')]])
      then $e/ArgumentList/*
      else if ($e/self::InfixExpression[@Operator = '==']) then $e/* else ()
    },
    $isKey := function($side, $p) {
      exists($side[self::MethodCall[ArgumentList/@Size = 0] or self::FieldAccess]//VariableAccess[@Name = $p])
    },
    $isProbe := function($side, $p) {
      empty($side/descendant-or-self::VariableAccess[@Name = $p])
      and not($side[self::StringLiteral or self::NumericLiteral or self::CharLiteral or self::BooleanLiteral
                    or self::NullLiteral or self::FieldAccess[*[1][self::TypeExpression]]])
    },
    $keyed := function($lambda) {
      let $p := $lambda/LambdaParameterList[count(LambdaParameter) = 1]/LambdaParameter/VariableId/@Name,
          $s := $sides($body($lambda))
      return exists($p) and count($s) = 2
        and (($isKey($s[1], $p) and $isProbe($s[2], $p)) or ($isKey($s[2], $p) and $isProbe($s[1], $p)))
    },
    $lookup := function($call) {
      if ($call/@MethodName = ('findFirst', 'findAny'))
      then $call[ArgumentList/@Size = 0]/*[1][self::MethodCall[@MethodName = 'filter']]
             [ArgumentList/*[1][self::LambdaExpression][$keyed(.)]]/*[1]
      else $call[ArgumentList/*[1][self::LambdaExpression][$keyed(.)]]/*[1]
    }
return //MethodCall[@MethodName = ('findFirst', 'findAny', 'anyMatch', 'noneMatch')]
  [let $call := .,
       $stream := $lookup(.)[self::MethodCall[@MethodName = 'stream'][ArgumentList/@Size = 0]],
       $source := $stream/*[1][self::VariableAccess or self::FieldAccess[*[1][self::ThisExpression[not(*)]]]],
       $name := $source/@Name,
       $block := ancestor::Block[LocalVariableDeclaration/VariableDeclarator/VariableId[@Name = $name]][1],
       $local := $block/LocalVariableDeclaration/VariableDeclarator[VariableId/@Name = $name],
       $method := ancestor::*[self::MethodDeclaration or self::ConstructorDeclaration][1],
       $bound := (ancestor::LambdaExpression/LambdaParameterList/LambdaParameter/VariableId
                  | ancestor::ForeachStatement/LocalVariableDeclaration/VariableDeclarator/VariableId
                  | ancestor::ForStatement/ForInit//VariableId)[@Name = $name],
       $parameter := $method/FormalParameters/FormalParameter/VariableId[@Name = $name],
       $scope := if (exists($local)) then $block
                 else if (exists($parameter)) then $method
                 else ancestor::*[self::ClassBody or self::RecordBody or self::EnumBody][1],
       $changes := ($scope//MethodCall[@MethodName = $mutators]
                      [*[1][self::VariableAccess[@Name = $name] or self::FieldAccess[@Name = $name][*[1][self::ThisExpression]]]]
                    | $scope//AssignmentExpression[*[1][@Name = $name]])
                   [empty(ancestor::ConstructorDeclaration) or exists($local) or exists($parameter)],
       $runs := ancestor::*[local-name() = $repeats or self::LambdaExpression[parent::ArgumentList/parent::MethodCall
                  [@MethodName = $iterating][*[1][pmd-java:typeIs('java.util.stream.BaseStream')
                    or pmd-java:typeIs('java.lang.Iterable') or pmd-java:typeIs('java.util.Map')]]]]
   return exists($name) and empty($bound) and empty($changes)
     and exists(if (exists($local)) then $runs[. >> $local] else $runs)]
